import math


def retry_delay(headers):
    try:
        delay = float(headers.get("Retry-After", ""))
    except (TypeError, ValueError):
        return 2.0
    return min(30.0, max(0.0, delay)) if math.isfinite(delay) else 2.0

def redact(value):
    if isinstance(value, dict):
        return {
            key: "[redacted]" if key.casefold() in {"token", "password", "api_key"} else redact(item)
            for key, item in value.items()
        }
    if isinstance(value, list):
        return [redact(item) for item in value]
    return value

from copy import deepcopy


def merge_config(base, override):
    result = deepcopy(base)
    for key, value in override.items():
        if value is None:
            result.pop(key, None)
        elif isinstance(value, dict):
            previous = result.get(key)
            result[key] = merge_config(previous if isinstance(previous, dict) else {}, value)
        else:
            result[key] = deepcopy(value)
    return result

def unique_names(names):
    seen, result = set(), []
    for name in names:
        key = name.strip().casefold()
        if key and key not in seen:
            seen.add(key)
            result.append(name)
    return result

from decimal import Decimal, ROUND_HALF_UP


def format_amount(value):
    rounded = Decimal(value).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    return "0.00" if rounded == 0 else format(rounded, ".2f")

def slice_after(items, after=None, limit=2):
    if limit < 0:
        raise ValueError("limit must be non-negative")
    start = 0
    if after is not None:
        start = next((index + 1 for index, item in enumerate(items) if item["id"] == after), len(items))
    return items[start:start + limit]

